package uk.ac.ravensbourne.casevault.service;
import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import uk.ac.ravensbourne.casevault.audit.*; import uk.ac.ravensbourne.casevault.domain.Role; import uk.ac.ravensbourne.casevault.security.UserPrincipal;
/** Read-only, paginated audit access for AUDITOR_ADMIN controllers. */
@Service public class AdminAuditService { private final JdbcTemplate jdbc; private final PersistentAuditService chain; private final AuditService audit; public AdminAuditService(JdbcTemplate j,PersistentAuditService c,AuditService a){jdbc=j;chain=c;audit=a;} public List<Map<String,Object>> events(UserPrincipal actor,int page,int size,String action){requireAdministrator(actor);int safe=Math.min(Math.max(size,1),50);String filter=action==null?"":" AND action=?";List<Object> args=new ArrayList<>();if(!filter.isBlank())args.add(action);args.add(safe);args.add(Math.max(page,0)*safe);return jdbc.queryForList("SELECT id,ts,actor_role,action,target_type,outcome,correlation_id FROM audit_events WHERE 1=1"+filter+" ORDER BY id DESC LIMIT ? OFFSET ?",args.toArray());} public AuditChainVerification verify(UserPrincipal actor){requireAdministrator(actor);AuditChainVerification result=chain.verifyChain();audit.record(actor,AuditEventType.AUDIT_VERIFY,"AUDIT",null,"audit-verify");return result;} public void viewed(UserPrincipal actor){requireAdministrator(actor);audit.record(actor,AuditEventType.ADMIN_VIEW_AUDIT,"AUDIT",null,"audit-viewed");} public void healthViewed(UserPrincipal actor){requireAdministrator(actor);audit.record(actor,AuditEventType.ADMIN_VIEW_HEALTH,"SYSTEM",null,"health-viewed");} private void requireAdministrator(UserPrincipal actor){if(actor==null||!Role.AUDITOR_ADMIN.name().equals(actor.role()))throw new AccessDeniedException("Administrative access is not permitted");} }
